const b = $json.body ?? $json;
const s = (v) => (v === undefined || v === null) ? '' : String(v).trim();
return [{ json: {
  name: s(b.name),
  email: s(b.email),
  message: s(b.message).slice(0, 1000),
  received_at: new Date().toISOString()
} }];

const j = $json;
const errors = [];
if (!j.message) errors.push('missing_message');
if (!j.name) errors.push('missing_name');
if (j.email && !(j.email.includes('@') && j.email.indexOf('@') > 0 && j.email.indexOf('@') < j.email.length - 1 && !/[ \t\n]/.test(j.email))) errors.push('invalid_email');
return [{ json: { ...j, valid: errors.length === 0, errors } }];

const sys = "You are a lead classifier for a home services company. Reply with ONLY one compact JSON object. No markdown, no code fences, no explanation. Schema: {\"category\":\"hvac|plumbing|general|other\",\"urgency\":\"low|medium|high\",\"intent\":\"service_request|quote_request|question|spam|other\",\"confidence\":0.0-1.0,\"reason\":\"one short sentence\"}";
const user = `Name: ${$json.name}\nEmail: ${$json.email}\nMessage: ${$json.message}`;
return [{ json: { ...$json, model: "zai-org/glm-5.3-flash",
  request: {
    model: "zai-org/glm-5.3-flash",
    max_tokens: 400,
    temperature: 0,
    messages: [
      { role: 'system', content: sys },
      { role: 'user', content: user }
    ]
  } } }];

// Upstream failure (HTTP error surfaced by the node) takes priority.
const errObj = $json.error ?? null;
let status = $json.status_code ?? $json.statusCode ?? 200;

function findChoices(o, depth) {
  if (!o || typeof o !== 'object' || depth > 5) return null;
  if (Array.isArray(o.choices) && o.choices.length) return o.choices;
  for (const k of ['body','data','json','response']) {
    const sub = o[k];
    if (sub && typeof sub === 'object') { const f = findChoices(sub, depth + 1); if (f) return f; }
  }
  return null;
}
if (errObj) {
  const httpCode = errObj.httpCode ?? errObj.statusCode ?? errObj.code ?? null;
  const msg = errObj.message ?? String(errObj);
  return [{ json: {
    upstream_status: (typeof httpCode === 'number' ? httpCode : 503),
    parse_error: null,
    schema_errors: [],
    classified: null,
    ok: false,
    upstream_error: String(msg).slice(0, 300)
  } }];
}

const choices = findChoices($json, 0);
const msg = choices?.[0]?.message ?? null;
let text = msg ? (msg.content ?? '') : (typeof $json === 'string' ? $json : '');

let parsed = null, parse_err = null;
const cleaned = String(text).replace(/```json|```/g, '').trim();
if (!cleaned) parse_err = 'empty_model_output';
else { try { parsed = JSON.parse(cleaned); } catch (e) { parse_err = 'malformed_json'; } }

const CAT = ['hvac','plumbing','general','other'];
const URG = ['low','medium','high'];
const INT = ['service_request','quote_request','question','spam','other'];
let schema_errors = [];
if (parsed) {
  if (!CAT.includes(parsed.category)) schema_errors.push('bad_category');
  if (!URG.includes(parsed.urgency)) schema_errors.push('bad_urgency');
  if (!INT.includes(parsed.intent)) schema_errors.push('bad_intent');
  const c = Number(parsed.confidence);
  if (!Number.isFinite(c) || c < 0 || c > 1) schema_errors.push('bad_confidence');
}
return [{ json: {
  upstream_status: status,
  parse_error: parse_err,
  schema_errors,
  classified: parsed,
  upstream_error: null,
  ok: !parse_err && schema_errors.length === 0 && status < 400
} }];

const j = $json;
let kind;
if (j.upstream_error !== null && j.upstream_error !== undefined) kind = 'upstream_failed';
else if (j.upstream_status >= 400) kind = 'upstream_failed';
else if (j.parse_error) kind = (j.parse_error === 'empty_model_output') ? 'empty_model_output' : 'malformed_llm_output';
else if (j.schema_errors && j.schema_errors.length) kind = 'schema_invalid';
else kind = 'unknown';
return [{ json: { ok: false, error: kind,
  upstream_status: j.upstream_status,
  details: j.upstream_error || j.parse_error || j.schema_errors || null,
  message: 'No classification produced. Refusing to return a fabricated result.' } }];

const c = $json.classified;
const queue = (c.category === 'hvac' || c.category === 'plumbing') ? 'field_team' : 'front_desk';
const sla = c.urgency === 'high' ? 'same_day' : (c.urgency === 'medium' ? '48h' : 'next_week');
return [{ json: { ok: true, category: c.category, urgency: c.urgency,
  intent: c.intent, confidence: Number(c.confidence), reason: c.reason,
  routing: { queue, sla } } }];
